class MysticCAS { private static final Object monitorC = new Object(); 
    private int value;

    public synchronized int get() { synchronized (monitorC) { 
        return value;
     } }

    public int compareAndSwap(int expected, int newValue) { synchronized (monitorC) { synchronized (this) { 
        int old = value;
        if (value == expected) {
            value = newValue;
        }
        return old;
     } } }
}

class DragonScaleCounter {
    private final MysticCAS cas = new MysticCAS();

    public int getScaleCount() {
        return cas.get();
    }

    public void growScale() {
        int old;
        int newValue;

        do {
            old = cas.get();
            newValue = old + 1;
        } while (cas.compareAndSwap(old, newValue) != old);
    }
}

class Sleeper {
    private boolean asleep;

    void tryToSleep() throws InterruptedException {
        while (!asleep) {
            wait();
        }
    }

    synchronized void setAsleep() {
        asleep = true;
        notifyAll();
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        Sleeper sleeper = new Sleeper();

        Thread reader = new Thread(() -> {
            try {
                sleeper.tryToSleep();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        Thread writer = new Thread(sleeper::setAsleep);

        reader.start();
        writer.start();

        reader.join();
        writer.join();
    }
}

